resume_evidence = []
jd_requirements = []


# =========================================================
# RESUME EVIDENCE
# =========================================================

# -------------------------
# Skills
# -------------------------

skills = resume.get("skills", {})

if isinstance(skills, dict):

    for category, skill_list in skills.items():

        if not isinstance(skill_list, list):
            continue

        for skill in skill_list:

            if not skill:
                continue

            resume_evidence.append({
                "id": f"skill_{len(resume_evidence) + 1}",
                "type": "skill",
                "category": category,
                "text": str(skill)
            })


# -------------------------
# Projects
# -------------------------

projects = resume.get("projects", [])

if isinstance(projects, list):

    for project in projects:

        project_name = project.get("name", "")

        description = project.get("description", "")

        technologies = project.get("technologies_used", [])

        bullets = project.get("bullets", [])

        # Project description
        if description:

            resume_evidence.append({
                "id": f"project_{len(resume_evidence) + 1}",
                "type": "project",
                "name": project_name,
                "text": description
            })

        # Project bullets
        if isinstance(bullets, list):

            for bullet in bullets:

                if not bullet:
                    continue

                # Avoid duplicating description
                if description and bullet.strip() == description.strip():
                    continue

                resume_evidence.append({
                    "id": f"project_{len(resume_evidence) + 1}",
                    "type": "project",
                    "name": project_name,
                    "text": bullet
                })

        # Technologies
        if isinstance(technologies, list):

            for technology in technologies:

                if not technology:
                    continue

                resume_evidence.append({
                    "id": f"project_tech_{len(resume_evidence) + 1}",
                    "type": "project_technology",
                    "name": project_name,
                    "text": str(technology)
                })


# -------------------------
# Experience
# -------------------------

experience = resume.get("experience", [])

if isinstance(experience, list):

    for exp in experience:

        company = exp.get("company", "")
        title = exp.get("title", "")

        responsibilities = exp.get("responsibilities", [])
        technologies = exp.get("technologies", [])

        for responsibility in responsibilities:

            if responsibility:

                resume_evidence.append({
                    "id": f"experience_{len(resume_evidence) + 1}",
                    "type": "experience",
                    "company": company,
                    "title": title,
                    "text": responsibility
                })

        for technology in technologies:

            if technology:

                resume_evidence.append({
                    "id": f"experience_tech_{len(resume_evidence) + 1}",
                    "type": "experience_technology",
                    "company": company,
                    "title": title,
                    "text": technology
                })


# -------------------------
# Education
# -------------------------

education = resume.get("education", [])

if isinstance(education, list):

    for edu in education:

        institution = edu.get("institution", "")
        degree = edu.get("degree", "")
        field = edu.get("field_of_study", "")
        gpa = edu.get("gpa", "")

        text_parts = [
            degree,
            field,
            institution
        ]

        if gpa:
            text_parts.append(f"GPA: {gpa}")

        text = " | ".join(
            str(x) for x in text_parts if x
        )

        if text:

            resume_evidence.append({
                "id": f"education_{len(resume_evidence) + 1}",
                "type": "education",
                "text": text
            })


# -------------------------
# Certifications
# -------------------------

certifications = resume.get("certifications", [])

if isinstance(certifications, list):

    for cert in certifications:

        if isinstance(cert, dict):

            name = cert.get("name", "")
            issuer = cert.get("issuer", "")

            text = f"{name} | {issuer}".strip(" |")

        else:
            text = str(cert)

        if text:

            resume_evidence.append({
                "id": f"certification_{len(resume_evidence) + 1}",
                "type": "certification",
                "text": text
            })


# -------------------------
# Extracurricular
# -------------------------

extracurricular = resume.get("extracurricular", [])

if isinstance(extracurricular, list):

    for activity in extracurricular:

        organization = activity.get("organization", "")
        role = activity.get("role", "")
        bullets = activity.get("bullets", [])

        for bullet in bullets:

            if bullet:

                resume_evidence.append({
                    "id": f"extracurricular_{len(resume_evidence) + 1}",
                    "type": "extracurricular",
                    "organization": organization,
                    "role": role,
                    "text": bullet
                })


# =========================================================
# JD REQUIREMENTS
# =========================================================

# -------------------------
# Technical skills
# -------------------------

jd_skills = jd.get("skills", [])

if isinstance(jd_skills, list):

    for skill in jd_skills:

        if not isinstance(skill, dict):
            continue

        name = skill.get("name", "")

        if not name:
            continue

        jd_requirements.append({
            "id": f"jd_skill_{len(jd_requirements) + 1}",
            "type": "technical_skill",
            "text": name,
            "category": skill.get("category"),
            "priority": skill.get("priority", "preferred")
        })


# -------------------------
# Responsibilities
# -------------------------

responsibilities = jd.get("responsibilities", [])

if isinstance(responsibilities, list):

    for responsibility in responsibilities:

        if not responsibility:
            continue

        jd_requirements.append({
            "id": f"jd_resp_{len(jd_requirements) + 1}",
            "type": "responsibility",
            "text": responsibility,
            "priority": "required"
        })


# -------------------------
# Education requirements
# -------------------------

education_requirements = jd.get(
    "education_requirements",
    []
)

if isinstance(education_requirements, list):

    for requirement in education_requirements:

        if not requirement:
            continue

        jd_requirements.append({
            "id": f"jd_edu_{len(jd_requirements) + 1}",
            "type": "education",
            "text": str(requirement),
            "priority": "required"
        })


# -------------------------
# Soft skills
# -------------------------

soft_skills = jd.get("soft_skills", [])

if isinstance(soft_skills, list):

    for skill in soft_skills:

        if not skill:
            continue

        jd_requirements.append({
            "id": f"jd_soft_{len(jd_requirements) + 1}",
            "type": "soft_skill",
            "text": str(skill),
            "priority": "preferred"
        })


# =========================================================
# OUTPUT
# =========================================================

return [
    {
        "json": {
            "resume_evidence": resume_evidence,
            "jd_requirements": jd_requirements
        }
    }
]

