import math

data = _items[0]["json"]

# -----------------------------------------
# Read merged data
# -----------------------------------------

embeddings = data["data"]
metadata = data["metadata"]

# -----------------------------------------
# Cosine similarity
# -----------------------------------------

def cosine_similarity(vec1, vec2):
    dot = 0.0
    norm1 = 0.0
    norm2 = 0.0

    for a, b in zip(vec1, vec2):
        dot += a * b
        norm1 += a * a
        norm2 += b * b

    if norm1 == 0 or norm2 == 0:
        return 0.0

    return dot / (math.sqrt(norm1) * math.sqrt(norm2))

# -----------------------------------------
# Attach vectors to metadata
# -----------------------------------------

resume_vectors = []
jd_vectors = []

for emb in embeddings:
    idx = emb["index"]

    item = {
        "embedding": emb["embedding"],
        "meta": metadata[idx]
    }

    if metadata[idx]["embedding_type"] == "resume_evidence":
        resume_vectors.append(item)

    elif metadata[idx]["embedding_type"] == "jd_requirement":
        jd_vectors.append(item)

# -----------------------------------------
# Retrieve Top 3 matches
# -----------------------------------------

semantic_matches = []

for jd in jd_vectors:

    candidates = []

    for resume in resume_vectors:

        similarity = cosine_similarity(
            jd["embedding"],
            resume["embedding"]
        )

        candidates.append({
            "similarity": round(similarity, 4),
            "evidence_id": resume["meta"]["source_id"],
            "evidence_type": resume["meta"]["source_type"],
            "evidence_name": resume["meta"].get("source_name"),
            "text": resume["meta"]["text"]
        })

    candidates.sort(
        key=lambda x: x["similarity"],
        reverse=True
    )

    semantic_matches.append({
        "requirement": {
            "id": jd["meta"]["source_id"],
            "type": jd["meta"]["source_type"],
            "text": jd["meta"]["text"],
            "priority": jd["meta"].get("priority")
        },
        "top_matches": candidates[:3]
    })

# -----------------------------------------
# Output
# -----------------------------------------

return [{
    "json": {
        "semantic_matches": semantic_matches,
        "statistics": {
            "resume_evidence_count": len(resume_vectors),
            "jd_requirement_count": len(jd_vectors)
        }
    }
}]

items = _items

data = items[0]["json"]

semantic_matches = data.get(
    "semantic_matches",
    []
)

judge_inputs = []

for match in semantic_matches:

    requirement = match["requirement"]

    top_matches = match.get(
