                requirement.get("priority")
        },

        "evidence":
            evidence
    })


return [
    {
        "json": {
            "judge_inputs": judge_inputs
        }
    }
]

data = _items[0]["json"]

final_evaluations = data.get(
    "final_evaluations",
    []
)

if not final_evaluations:
    raise Exception("No final evaluations found.")

# Evidence id -> resume text, so each requirement can show
# the actual resume lines it was matched on (not just ids).
evidence_text = {
    e.get("id"): e.get("text", "")
    for e in data.get("resume_evidence", [])
    if isinstance(e, dict)
}


# =====================================================
# CONFIGURATION
# =====================================================

DECISION_SCORES = {
    "EXACT": 1.00,
    "STRONG_MATCH": 0.85,
    "PARTIAL": 0.50,
    "NO_MATCH": 0.00,
    "INSUFFICIENT_EVIDENCE": 0.00
}

PRIORITY_WEIGHTS = {
    "required": 1.0,
    "preferred": 0.5
}

CATEGORY_WEIGHTS = {
    "technical_skill": 0.40,
    "responsibility": 0.40,
    "education": 0.10,
    "soft_skill": 0.10
}


# =====================================================
# CALCULATE REQUIREMENT SCORE
# =====================================================

def get_requirement_score(evaluation):

    decision = evaluation.get(
        "decision"
    )

    if decision == "NOT_APPLICABLE":
        return None

    base_score = DECISION_SCORES.get(
        decision,
        0.0
    )

    priority = evaluation.get(
        "priority",
        "required"
    )

    priority_weight = PRIORITY_WEIGHTS.get(
        priority,
        1.0
    )

    weighted_score = (
        base_score *
        priority_weight
    )

    return weighted_score


# =====================================================
# GROUP BY CATEGORY
# =====================================================

categories = {
    "technical_skill": [],
    "responsibility": [],
    "education": [],
    "soft_skill": []
}

for evaluation in final_evaluations:

    category = evaluation.get(
        "type"
    )

    if category in categories:

        categories[category].append(
            evaluation
        )


# =====================================================
# CATEGORY SCORING
# =====================================================

category_results = {}

for category, evaluations in categories.items():

    total_score = 0.0
    maximum_score = 0.0

    evaluated_count = 0
    not_applicable_count = 0

    for evaluation in evaluations:

        if evaluation.get(
            "decision"
        ) == "NOT_APPLICABLE":

            not_applicable_count += 1
            continue

        priority = evaluation.get(
            "priority",
            "required"
        )

        priority_weight = PRIORITY_WEIGHTS.get(
            priority,
            1.0
        )

        score = get_requirement_score(
            evaluation
        )

        total_score += score
        maximum_score += priority_weight

        evaluated_count += 1


    if maximum_score > 0:

        percentage = (
            total_score /
            maximum_score
        ) * 100

    else:

        percentage = 0.0


    category_results[category] = {

        "score":
            round(
                total_score,
                4
            ),

        "maximum_score":
            round(
                maximum_score,
                4
            ),

        "percentage":
            round(
                percentage,
                2
            ),

        "evaluated_requirements":
            evaluated_count,

        "total_requirements":
            len(evaluations),

        "not_applicable":
            not_applicable_count
    }


# =====================================================
# WEIGHTED ATS SCORE
# =====================================================

weighted_total = 0.0
active_category_weight = 0.0

for category, category_weight in CATEGORY_WEIGHTS.items():

    result = category_results.get(
        category
    )

    if not result:
        continue

    # Do not penalize the candidate if a category
    # does not exist in the JD.
    if result["evaluated_requirements"] == 0:
        continue

    weighted_total += (
        result["percentage"] *
        category_weight
    )

    active_category_weight += (
        category_weight
    )


if active_category_weight > 0:

    ats_score = (
        weighted_total /
        active_category_weight
    )

else:

    ats_score = 0.0


ats_score = round(
    max(
        0.0,
        min(
            ats_score,
            100.0
        )
    ),
    2
)


# =====================================================
# REQUIREMENT LEVEL SCORES
# =====================================================

requirement_scores = []

for evaluation in final_evaluations:

    decision = evaluation.get(
        "decision"
    )

    score = get_requirement_score(
        evaluation
    )

    priority = evaluation.get(
        "priority",
        "required"
    )

    requirement_scores.append({

        "requirement_id":
            evaluation.get(
                "requirement_id"
            ),

        "text":
            evaluation.get(
                "text"
            ),

        "type":
            evaluation.get(
                "type"
            ),

        "priority":
            priority,

        "decision":
            decision,

        "confidence":
            evaluation.get(
                "confidence"
            ),

        "base_score":
            None
            if decision == "NOT_APPLICABLE"
            else DECISION_SCORES.get(
                decision,
                0.0
            ),

        "priority_weight":
            None
            if decision == "NOT_APPLICABLE"
            else PRIORITY_WEIGHTS.get(
                priority,
                1.0
            ),

        "weighted_score":
            None
            if score is None
            else round(
                score,
                4
            ),

        "match_method":
            evaluation.get(
                "match_method"
            ),

        "evidence_ids":
            evaluation.get(
                "evidence_ids",
                []
            ),

        "comment":
            evaluation.get(
                "comment",
                ""
            ),

        # Unknown ids (e.g. cited by the LLM judge but not in
        # the resume evidence) are skipped instead of failing.
        "evidence": [
            {"id": evidence_id, "text": evidence_text[evidence_id]}
            for evidence_id in evaluation.get("evidence_ids", [])
            if evidence_id in evidence_text
        ]
    })


# =====================================================
# DECISION COUNTS
# =====================================================

decision_counts = {
    "EXACT": 0,
    "STRONG_MATCH": 0,
    "PARTIAL": 0,
    "NO_MATCH": 0,
    "INSUFFICIENT_EVIDENCE": 0,
    "NOT_APPLICABLE": 0
}

for evaluation in final_evaluations:

    decision = evaluation.get(
        "decision"
    )

    if decision in decision_counts:

        decision_counts[
            decision
        ] += 1


# =====================================================
# CONFIDENCE SUMMARY
# =====================================================

confidence_values = []

for evaluation in final_evaluations:

    if evaluation.get(
        "decision"
    ) == "NOT_APPLICABLE":

        continue

    confidence = evaluation.get(
        "confidence"
    )

    if isinstance(
        confidence,
        (int, float)
    ):

        confidence_values.append(
            confidence
        )


if confidence_values:

    average_confidence = (
        sum(confidence_values) /
        len(confidence_values)
    )

else:

    average_confidence = 0.0


# =====================================================
# OUTPUT
# =====================================================

return [
    {
        "json": {

            "ats_score":
                ats_score,

            "score_version":
                "v2",

            "scoring_model": {

                "decision_scores":
                    DECISION_SCORES,

                "priority_weights":
                    PRIORITY_WEIGHTS,

                "category_weights":
                    CATEGORY_WEIGHTS
            },

            "category_scores":
                category_results,

            "decision_counts":
                decision_counts,

            "confidence_summary": {

                "average_confidence":
                    round(
                        average_confidence,
                        4
                    ),

                "evaluations_with_confidence":
                    len(
                        confidence_values
                    )
            },

            "requirement_scores":
                requirement_scores
        }
    }
]

